package com.neocoffee.smsgateway;
import android.app.Activity;import android.content.*;import org.json.JSONObject;import java.io.OutputStream;import java.nio.charset.StandardCharsets;import java.text.DateFormat;import java.util.Date;import java.util.concurrent.Executors;
public class SmsResultReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context context,Intent intent){PendingResult pending=goAsync();Executors.newSingleThreadExecutor().execute(()->{int id=intent.getIntExtra("id",0),resultCode=getResultCode();boolean sent=resultCode==Activity.RESULT_OK||resultCode==Activity.RESULT_CANCELED;String result=sent?"sent":"failed",error=sent?null:"Android SMS error "+resultCode;String phone=intent.getStringExtra("phone"),sim=intent.getStringExtra("sim");MessageLog.add(context,phone,intent.getBooleanExtra("test",false)?"اختبار":"OTP",sim==null?"الخط المختار":sim,result);try{if(!intent.getBooleanExtra("test",false)){var c=GatewayService.open(intent.getStringExtra("base")+"/api/sms-gateway/jobs",intent.getStringExtra("token"),"PATCH");c.setDoOutput(true);String json=new JSONObject().put("id",id).put("status",result).put("error",error).toString();try(OutputStream out=c.getOutputStream()){out.write(json.getBytes(StandardCharsets.UTF_8));}c.getResponseCode();}context.getSharedPreferences("gateway",Context.MODE_PRIVATE).edit().putString("last",DateFormat.getDateTimeInstance().format(new Date())+" — "+(sent?"تم إرسال الرسالة بنجاح":"فشل الإرسال وسيعاد تلقائيًا")).apply();}catch(Exception ignored){}finally{pending.finish();}});}
}
